(function(root){'use strict';
 const UI=()=>root.ND_CITY_MAP,D=root.ND_MAP_DATA,R=root.ND_MAP_ROUTING,h=x=>UI().h(x);let campaigns=[],selectedCampaign=null,draft=null,busy=false;
 function requireMaster(){if(!portalMaster)throw Error('Нужны права Мастера');}
 function error(e){UI().message(e.message);const el=document.querySelector('#map-admin-error');if(el)el.textContent=e.message;}
 async function show(){try{requireMaster();await masterReady();campaigns=await C.campaigns();if(selectedCampaign&&!campaigns.some(c=>c.id===selectedCampaign))selectedCampaign=null;portalView='master-map';portalShell('Карта города','Редактор районов, локаций и маршрутов',masterNavigation()+'<div class="map-admin-toolbar"><label>Область данных <select id="map-admin-campaign"><option value="">Общая карта · без положения группы</option>'+campaigns.map(c=>'<option value="'+c.id+'" '+(selectedCampaign===c.id?'selected':'')+'>'+h(c.name)+'</option>').join('')+'</select></label><button id="map-add-location" class="yellow">+ Добавить локацию</button><button id="map-set-party">Положение группы</button><button id="map-edit-settings">Масштаб и маршруты</button><button id="map-add-edge">Добавить переход</button></div><div class="master-map-layout"><div>'+UI().render()+'</div><aside id="map-admin-panel" aria-label="Редактор карты"></aside></div>');bindMasterNavigation();document.querySelector('#map-admin-campaign').onchange=e=>{if(draft){e.target.value=selectedCampaign||'';return error(Error('Сначала сохрани или отмени изменения'));}selectedCampaign=e.target.value||null;UI().bind({master:true,campaign:selectedCampaign});};document.querySelector('#map-add-location').onclick=()=>startLocation();document.querySelector('#map-set-party').onclick=()=>party();document.querySelector('#map-edit-settings').onclick=()=>settings();document.querySelector('#map-add-edge').onclick=()=>startEdge();await UI().bind({master:true,campaign:selectedCampaign});}catch(e){portalError(e);}}
 const panel=()=>document.querySelector('#map-admin-panel');
 function loaded(data){if(draft)return;panel().innerHTML='<h2>Управление картой</h2><p>Выбери район или локацию на карте для редактирования.</p><h3>Районы</h3>'+data.districts.map(d=>'<button data-admin-district="'+h(d.id)+'">'+h(d.name)+'<small>'+(d.contour_status==='confirmed'?'Контур подтверждён':'Контур требует проверки')+'</small></button>').join('')+'<h3>Разрешённые переходы</h3>'+(data.edges.map(e=>'<button data-admin-edge="'+e.id+'">'+e.aq+','+e.ar+' ↔ '+e.bq+','+e.br+(e.blocked?' · закрыт':'')+'</button>').join('')||'<p>Граф ещё не размечен. Игрокам доступна только предварительная оценка.</p>')+'<h3>Геометрия JSON</h3><button id="map-export-geometry">Экспорт геометрии</button><label class="map-import-label">Импорт геометрии<input type="file" id="map-import-geometry" accept="application/json,.json"></label><p id="map-admin-error" role="alert"></p>';panel().querySelectorAll('[data-admin-district]').forEach(b=>b.onclick=()=>UI().select('district',data.districts.find(d=>d.id===b.dataset.adminDistrict)));panel().querySelectorAll('[data-admin-edge]').forEach(b=>b.onclick=()=>edgeForm(data.edges.find(e=>e.id===b.dataset.adminEdge)));document.querySelector('#map-export-geometry').onclick=()=>{const blob=new Blob([JSON.stringify({version:1,width:6636,height:3792,districts:data.districts.map(({id,polygons,contour_status})=>({id,polygons,contour_status}))},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='new-detroit-geometry.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};document.querySelector('#map-import-geometry').onchange=async e=>{try{requireMaster();const file=e.target.files[0];if(!file)return;if(file.size>1000000)throw Error('Геометрия: файл не более 1 МБ');const value=JSON.parse(await file.text());if(value.version!==1||value.width!==6636||value.height!==3792||!Array.isArray(value.districts)||value.districts.length>50)throw Error('Неподходящий формат геометрии');const ids=new Set();for(const d of value.districts){validatePolygons(d.polygons);if(ids.has(d.id)||!data.districts.some(x=>x.id===d.id))throw Error('Неизвестный или повторяющийся район');ids.add(d.id);}draft={type:'import'};confirm('Применить геометрию?', 'Будут изменены контуры '+value.districts.length+' районов. Их статус станет «требует проверки».',async()=>{await C.mapImportGeometry(value.districts.map(d=>({id:d.id,polygons:d.polygons,revision:UI().context().data.districts.find(x=>x.id===d.id).revision})));await finish();},()=>{draft=null;loaded(data);});}catch(err){draft=null;error(err);e.target.value='';}};}
 function validatePolygons(polys){if(!Array.isArray(polys)||polys.length>20||polys.some(p=>!Array.isArray(p)||p.length<3||p.length>500||p.some(q=>!R.point(q))))throw Error('Некорректная геометрия: до 20 контуров, от 3 до 500 точек на контур');return polys;}
 function begin(type,row){requireMaster();if(draft)throw Error('Сначала сохрани или отмени текущие изменения');draft={type,row,values:row?JSON.parse(JSON.stringify(row)):{}};UI().closeInfo();return draft;}
 function cancel(){if(busy)return;draft=null;UI().clearDraft();loaded(UI().context().data);}
 async function finish(){draft=null;busy=false;UI().clearDraft();await UI().load();}
 async function write(table,value,row){requireMaster();return C.writeMaster(table,value,row);}
 function confirm(title,text,yes,no=()=>{}){modal(title,'<p>'+h(text)+'</p><button class="yellow" id="map-confirm">Подтвердить</button><button id="map-confirm-cancel">Отмена</button>');document.querySelector('#map-confirm-cancel').onclick=()=>{closeModal();no();};document.querySelector('#close-modal').onclick=()=>{closeModal();no();};document.querySelector('#dialog').oncancel=()=>{no();};document.querySelector('#map-confirm').onclick=async()=>{try{requireMaster();document.querySelector('#map-confirm').disabled=true;await yes();closeModal();}catch(e){document.querySelector('#dialog-error').textContent=e.message;document.querySelector('#map-confirm').disabled=false;}};}
 function controls(){return '<p id="map-admin-error" role="alert"></p><div class="map-admin-actions"><button class="yellow" type="submit">Сохранить</button><button type="button" id="map-admin-cancel">Отмена</button></div>';}
 function input(name,label,value='',type='text',max=200){return '<label>'+label+'<input name="'+name+'" type="'+type+'" '+(type==='text'?'maxlength="'+max+'"':'')+' value="'+h(value)+'"></label>';}
 function textarea(name,label,value='',max=20000){return '<label>'+label+'<textarea name="'+name+'" maxlength="'+max+'" rows="4">'+h(value)+'</textarea></label>';}
 function imageControl(image){return input('image','Изображение: HTTPS-ссылка или загруженный файл',image||'','text',700000)+'<label>Загрузить изображение<input id="map-image-file" type="file" accept="image/png,image/jpeg,image/webp"></label>'+(image?'<button type="button" id="map-remove-image">Убрать изображение</button>':'');}
 function bindImage(form){const file=document.querySelector('#map-image-file');if(!file)return;file.onchange=async()=>{try{const f=file.files[0];if(!f)return;if(!['image/png','image/jpeg','image/webp'].includes(f.type)||f.size>12000000)throw Error('PNG, JPEG или WebP до 12 МБ');const bitmap=await createImageBitmap(f),canvas=document.createElement('canvas'),k=Math.min(1,640/bitmap.width,640/bitmap.height);canvas.width=Math.max(1,Math.round(bitmap.width*k));canvas.height=Math.max(1,Math.round(bitmap.height*k));canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();let result=canvas.toDataURL('image/webp',.82);if(result.length>700000)throw Error('Изображение слишком сложное: выбери меньший файл');form.elements.namedItem('image').value=result;}catch(e){error(e);}};const remove=document.querySelector('#map-remove-image');if(remove)remove.onclick=()=>{form.elements.namedItem('image').value='';};}
 function bindForm(save){const form=panel().querySelector('form');document.querySelector('#map-admin-cancel').onclick=cancel;form.onsubmit=async e=>{e.preventDefault();if(busy)return;try{requireMaster();busy=true;form.querySelector('[type=submit]').disabled=true;await save(new FormData(form));await finish();}catch(err){error(err);busy=false;form.querySelector('[type=submit]').disabled=false;}};bindImage(form);return form;}
 function safe(fn){try{return fn();}catch(e){error(e);}}
 function startLocation(){safe(()=>{begin('location');UI().closeInfo();panel().innerHTML='<h2>Новая локация</h2><p>Нажми на карте, чтобы выбрать положение локации.</p><button id="map-admin-cancel">Отмена</button>';document.querySelector('#map-admin-cancel').onclick=cancel;UI().pickPoint('Выбери положение новой локации',p=>{UI().clearPick();locationForm(null,p);});});}
 function editLocation(row){safe(()=>{begin('location',row);locationForm(row,row.position);});}
 function locationForm(row,p){draft.values={...draft.values,position:p};const v=draft.values;panel().innerHTML='<h2>'+(row?'Редактировать локацию':'Новая локация')+'</h2><form>'+input('name','Название',v.name||'')+'<label>Категория<select name="category">'+Object.entries(D.categories).map(([id,n])=>'<option value="'+id+'" '+(v.category===id?'selected':'')+'>'+h(n)+'</option>').join('')+'</select></label><label>Район<select name="district_id"><option value="">Не задан</option>'+UI().context().data.districts.map(d=>'<option value="'+d.id+'" '+(v.district_id===d.id?'selected':'')+'>'+h(d.name)+'</option>').join('')+'</select></label>'+textarea('short_description','Краткое описание',v.short_description,2000)+textarea('description','Полное описание',v.description)+textarea('details','Дополнительные сведения',v.details,10000)+input('npc','Связанные NPC',v.npc||'','text',2000)+imageControl(v.image)+'<label>Видимость<select name="visibility">'+[['public','Публичная'],['campaign','Для кампании'],['hidden','Только Мастер']].map(([id,n])=>'<option value="'+id+'" '+(v.visibility===id?'selected':'')+'>'+n+'</option>').join('')+'</select></label><label>Кампания<select name="campaign_id"><option value="">Общая локация</option>'+campaigns.map(c=>'<option value="'+c.id+'" '+((v.campaign_id||selectedCampaign)===c.id?'selected':'')+'>'+h(c.name)+'</option>').join('')+'</select></label><label class="map-check"><input name="locked" type="checkbox" '+(v.locked?'checked':'')+'>Известная, но недоступная локация</label><p>Положение задаётся на карте. Перетащи белую точку, чтобы уточнить его.</p>'+controls()+'</form>';const form=bindForm(async f=>{const value=Object.fromEntries(f);delete value.locked;value.locked=f.has('locked');value.campaign_id=value.campaign_id||null;value.district_id=value.district_id||null;value.position=draft.values.position;value.image=value.image?D.image(value.image):null;if(!value.name.trim())throw Error('Укажи название');if(f.get('image')&&!value.image)throw Error('Нужна HTTPS-ссылка или PNG/JPEG/WebP');if(value.visibility==='campaign'&&!value.campaign_id)throw Error('Выбери кампанию');await write('map_locations',value,row);});form.elements.namedItem('name').required=true;UI().draftMarkers([p],(_,next)=>{if(next){draft.values.position=next;}});}
 function move(row){safe(()=>{begin('move',row);UI().closeInfo();panel().innerHTML='<h2>Переместить: '+h(row.name)+'</h2><p>Нажми на новое место или перетащи белый маркер. Положение сохраняется только после подтверждения.</p><form>'+controls()+'</form>';const update=p=>{draft.values.position=p;UI().draftMarkers([p],(_,q)=>{if(q)draft.values.position=q;});};update(row.position);UI().pickPoint('Выбери новое положение локации',update);bindForm(()=>write('map_locations',{position:draft.values.position},row));});}
 function remove(row){safe(()=>{requireMaster();confirm('Удалить локацию?',row.name,async()=>{await C.deleteMaster('map_locations',row);UI().closeInfo();await UI().load();});});}
 function editDistrict(row){safe(()=>{begin('district',row);panel().innerHTML='<h2>'+h(row.name)+'</h2><form>'+input('name','Название',row.name)+textarea('short_description','Краткое описание',row.short_description,2000)+textarea('description','Описание',row.description)+input('security','Безопасность',row.security)+input('control','Корпоративный контроль',row.control)+input('activity','Сфера деятельности',row.activity,'text',300)+imageControl(row.image)+'<label>Видимость<select name="visibility"><option value="public">Публичный район</option><option value="hidden" '+(row.visibility==='hidden'?'selected':'')+'>Только Мастер</option></select></label>'+input('color','Цвет границы',row.color,'color')+'<label class="map-check"><input type="checkbox" name="confirmed" '+(row.contour_status==='confirmed'?'checked':'')+'>Контур проверен и подтверждён</label>'+controls()+'</form>';bindForm(f=>{const v=Object.fromEntries(f);delete v.confirmed;v.contour_status=f.has('confirmed')?'confirmed':'draft';v.image=v.image?D.image(v.image):null;if(f.get('image')&&!v.image)throw Error('Некорректное изображение');if(!v.name.trim())throw Error('Укажи название');return write('map_districts',v,row);});});}
 function geometry(row){safe(()=>{begin('geometry',row);draft.index=0;draft.values.polygons=JSON.parse(JSON.stringify(row.polygons));geometryPanel();});}
 function geometryPanel(){const polys=draft.values.polygons,index=draft.index;panel().innerHTML='<h2>Границы: '+h(draft.row.name)+'</h2><p>Нажимай на карте для добавления точек. Перетаскивай пронумерованные вершины. Удаляй вершины кнопками ниже. Несколько контуров могут относиться к одному району.</p><label>Контур<select id="map-polygon-index">'+polys.map((p,i)=>'<option value="'+i+'" '+(i===index?'selected':'')+'>Контур '+(i+1)+' · '+p.length+' вершин</option>').join('')+'</select></label><button id="map-finish-polygon">Завершить контур</button><button id="map-new-polygon">Добавить контур</button><button id="map-delete-polygon">Удалить текущий контур</button><div class="map-vertices">'+(polys[index]||[]).map((_,i)=>'<button data-map-remove-vertex="'+i+'" title="Удалить вершину '+(i+1)+'">'+(i+1)+' ×</button>').join('')+'</div><form><label class="map-check"><input type="checkbox" name="confirmed">Подтверждаю соответствие границ изображению</label>'+controls()+'</form>';document.querySelector('#map-polygon-index').onchange=e=>{draft.index=Number(e.target.value);geometryPanel();};document.querySelector('#map-finish-polygon').onclick=()=>{if((polys[index]||[]).length<3)return error(Error('В контуре должно быть не менее трёх вершин'));UI().clearPick();UI().message('Контур завершён. Сохрани изменения или добавь следующий контур.');};document.querySelector('#map-new-polygon').onclick=()=>{if(polys.length>=20)return error(Error('Не более 20 контуров'));polys.push([]);draft.index=polys.length-1;geometryPanel();};document.querySelector('#map-delete-polygon').onclick=()=>confirm('Удалить контур?',polys.length===1?'Это последний контур района. Район перестанет выбираться на карте до новой разметки.':'Контур будет удалён после сохранения.',()=>{polys.splice(index,1);draft.index=Math.max(0,index-1);geometryPanel();});document.querySelectorAll('[data-map-remove-vertex]').forEach(b=>b.onclick=()=>{polys[index].splice(Number(b.dataset.mapRemoveVertex),1);geometryPanel();});const change=(i,p)=>{if(p)polys[index][i]=p;else polys[index].splice(i,1);geometryPanel();};UI().draftMarkers(polys[index]||[],change,true);UI().pickPoint('Разметка границ · нажми, чтобы добавить вершину',p=>{if(!polys.length){polys.push([]);draft.index=0;}if(polys[draft.index].length>=500)return error(Error('Не более 500 точек'));polys[draft.index].push(p);geometryPanel();});bindForm(f=>{validatePolygons(polys);return write('map_districts',{polygons:polys,contour_status:f.has('confirmed')?'confirmed':'draft'},draft.row);});}
 function party(){safe(()=>{if(!selectedCampaign)throw Error('Сначала выбери кампанию');const old=UI().context().data.party;begin('party',old);draft.values.position=old?.position||null;panel().innerHTML='<h2>Положение группы</h2><p>Выбери точку на карте. Игроки не могут менять это положение.</p><form>'+input('label','Название группы / места',old?.label||'Группа')+controls()+'</form>';UI().pickPoint('Выбери положение группы',p=>{draft.values.position=p;UI().draftMarkers([p],(_,q)=>{if(q)draft.values.position=q;});});bindForm(f=>{if(!draft.values.position)throw Error('Выбери точку на карте');return write('map_campaign_state',{id:selectedCampaign,position:draft.values.position,label:f.get('label')||'Группа'},old);});});}
 function settings(){safe(()=>{const context=UI().context(),old=context.data.settings;begin('settings',old);const c=context.config;panel().innerHTML='<h2>Масштаб и маршруты</h2><p>Исходная ширина городской территории: 82% изображения. Базовая калибровка — пересечение города примерно за 5 часов на автомобиле. Изменение сетки требует повторной проверки переходов.</p><form>'+input('crossingHours','Часов на пересечение города',c.crossingHours,'number')+input('carHours','Часов на шаг: автомобиль',c.carHours,'number')+input('footHours','Часов на шаг: пешком',c.footHours,'number')+input('scaleFactor','Поправка размера гекса',c.scaleFactor,'number')+'<label class="map-check"><input type="checkbox" name="routingConfirmed" '+(c.routingConfirmed?'checked':'')+'>Разрешённые переходы проверены; маршруты можно отображать</label><p>Через воду разрешай переход только после проверки моста или переправы. Пока граф не подтверждён, линия маршрута не рисуется.</p>'+controls()+'</form>';const form=bindForm(f=>{const next={...c};for(const k of ['crossingHours','carHours','footHours','scaleFactor'])next[k]=Number(f.get(k));const gridChanged=['crossingHours','carHours','scaleFactor'].some(k=>next[k]!==c[k]);next.routingConfirmed=!gridChanged&&f.has('routingConfirmed');R.config(next);return write('map_settings',{id:'global',data:next},old);});form.querySelectorAll('input[type=number]').forEach(x=>x.step='0.1');});}
 function startEdge(){safe(()=>{begin('edge');draft.points=[];panel().innerHTML='<h2>Разрешённый переход</h2><p>Выбери два соседних гекса по подтверждённой дороге или тропе. Переход через воду требует существующей переправы.</p><button id="map-admin-cancel">Отмена</button>';document.querySelector('#map-admin-cancel').onclick=cancel;UI().pickPoint('Выбери два соседних гекса',p=>{draft.points.push(R.hex(p,UI().context().config));UI().draftMarkers(draft.points.map(q=>R.center(q,UI().context().config)),()=>{});if(draft.points.length===2){const [a,b]=draft.points;if(R.distance(a,b)!==1){draft.points=[];return error(Error('Нужны два соседних гекса. Начни выбор заново.'));}UI().clearPick();edgeForm(null,{aq:a.q,ar:a.r,bq:b.q,br:b.r,car:true,foot:true,cost:1});}});});}
 function edgeForm(row,initial){safe(()=>{if(row)begin('edge',row);const v=row||initial;draft.values=v;panel().innerHTML='<h2>Переход '+v.aq+','+v.ar+' ↔ '+v.bq+','+v.br+'</h2><form>'+['car','foot','blocked','crossing'].map(k=>'<label class="map-check"><input type="checkbox" name="'+k+'" '+(v[k]?'checked':'')+'>'+({car:'Автомобиль',foot:'Пешком',blocked:'Переход закрыт',crossing:'Проверенный мост / переправа'})[k]+'</label>').join('')+input('cost','Стоимость в гексагональных шагах',v.cost,'number')+'<p>Подтверждай только реально проходимые соединения. Линия маршрута проходит через центры выбранных соседних гексов.</p>'+controls()+'</form>'+(row?'<button id="map-delete-edge">Удалить переход</button>':'');const form=bindForm(f=>{const next={aq:v.aq,ar:v.ar,bq:v.bq,br:v.br,car:f.has('car'),foot:f.has('foot'),blocked:f.has('blocked'),crossing:f.has('crossing'),cost:Number(f.get('cost')),campaign_id:row?row.campaign_id:selectedCampaign};R.edge(next);return write('map_route_edges',next,row);});form.elements.namedItem('cost').step='.25';if(row)document.querySelector('#map-delete-edge').onclick=()=>confirm('Удалить переход?','Он больше не будет участвовать в построении маршрутов.',async()=>{await C.deleteMaster('map_route_edges',row);await finish();});});}
 root.addEventListener?.('beforeunload',e=>{if(draft){e.preventDefault();e.returnValue='';}});
 root.ND_MASTER_MAP={show,loaded,editLocation,editDistrict,geometry,move,remove,cancel,hasDraft:()=>!!draft,validatePolygons};
})(typeof window!=='undefined'?window:globalThis);
